import sys, unicodedata, shutil, os
D = r'C:\Users\DELL\Desktop\AI_CAD\AI_Work\Thang-11\26-11-2026\521126-14'
T = r'C:\Users\DELL\AppData\Local\Temp\ai_cad_521126-14'

def load(p):
    return open(p, 'rb').read().decode('cp932').split('\r\n')

def chunks(L):
    i = L.index('ENTITIES') + 1
    j = L.index('ENDSEC', i) - 1
    idx = [k for k in range(i, j, 2) if L[k] == '  0']
    idx.append(j)
    return i, j, [(idx[n], idx[n + 1]) for n in range(len(idx) - 1)]

def val(ch, code):
    for k in range(0, len(ch) - 1, 2):
        if ch[k].strip() == code:
            return ch[k + 1]

def esc(s):
    s = unicodedata.normalize('NFC', s)
    return ''.join(c if ord(c) < 128 else '\\U+%04X' % ord(c) for c in s)

def wrap(s, n=40):
    out = []; cur = ''
    for w in s.split(' '):
        if cur and len(cur) + 1 + len(w) > n:
            out.append(cur); cur = w
        else:
            cur = (cur + ' ' + w) if cur else w
    if cur: out.append(cur)
    return out

def remove_circle(L, cx, cy, tol=0.01):
    i, j, cs = chunks(L)
    keep = []
    removed = 0
    for a, b in cs:
        ch = L[a:b]
        if ch[1] == 'CIRCLE' and abs(float(val(ch, '10')) - cx) < tol and abs(float(val(ch, '20')) - cy) < tol:
            removed += 1
            continue
        keep.extend(ch)
    assert removed == 1, removed
    return L[:i] + keep + L[j:]

def replace_flags(L, label_y, ylo, yhi, flags):
    """remove TEXT color 6 with y in [ylo,yhi], add new flags under label at label_y"""
    i, j, cs = chunks(L)
    keep = []; handles = []; template = None; pos = None
    for a, b in cs:
        ch = L[a:b]
        if ch[1] == 'TEXT' and val(ch, '62') == '6' and ylo <= float(val(ch, '20')) <= yhi:
            handles.append(val(ch, '5'))
            if template is None: template = ch
            if pos is None: pos = len(keep)
            continue
        keep.extend(ch)
    new = []
    k = 0
    for n, fl in enumerate(flags):
        for line in wrap(fl):
            ch = list(template)
            for q in range(0, len(ch) - 1, 2):
                c = ch[q].strip()
                if c == '5': ch[q + 1] = handles.pop(0)
                elif c == '20': ch[q + 1] = ('%.8f' % (label_y - 12 - 7 * k)).rstrip('0').rstrip('.')
                elif c == '1': ch[q + 1] = esc(line)
            new.extend(ch); k += 1
    if pos is None: pos = len(keep)
    keep = keep[:pos] + new + keep[pos:]
    return L[:i] + keep + L[j:]

def save(L, p):
    open(p, 'wb').write('\r\n'.join(L).encode('cp932'))

if __name__ == '__main__':
    # individual files
    p = D + r'\26-071754.dxf'; L = load(p); L = remove_circle(L, 23.88, 48.66); save(L, p)
    p = D + r'\26-071756.dxf'; L = load(p); L = remove_circle(L, 25.65, 16.13); save(L, p)
