    L = remove_circle(L, 25.65, 485 + 16.13)
    f54 = ['1. Thiếu kích thước (khe V giữa hai nửa cánh tại chỗ uốn 150° dựng theo đường phân giác từ hình DXF khách, bản vẽ không ghi)']
    f55 = ['1. Thiếu hoặc không chắc kích thước (bản vẽ chỉ ghi chữ A, B cho hai tấm 2.3t là 071754/071755: đã vẽ 071754 = tấm uốn chính A+B uốn 150°, 071755 = tấm uốn đầu phải 60 rộng; tấm bịt đầu trái chưa thấy mã riêng)']
    L = replace_flags(L, 1149.585, 1100, 1140, f54)
    L = replace_flags(L, 745.0, 660, 735, f55)
    L = replace_flags(L, 500.0, 455, 490, [])
